import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matrix_multiply_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdio>

__global__ void matrix_multiply_kernel(const float* A, const float* B, float* C,
                                       int M, int K, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float val = 0.0f;
        for (int i = 0; i < K; i++) {
            val += A[row * K + i] * B[i * N + col];
        }
        C[row * N + col] = val;
    }
}

torch::Tensor matrix_multiply_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure input tensors are float and on CUDA
    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);
    int K2 = B.size(0);
    int N = B.size(1);

    // Simple check
    TORCH_CHECK(K == K2, "Inner dimensions must match.");

    auto options = A.options();
    auto C = torch::zeros({M, N}, options);

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    matrix_multiply_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, N
    );

    return C;
}
""";

matrix_multiply_cpp_source = r"""
torch::Tensor matrix_multiply_cuda(torch::Tensor A, torch::Tensor B);
""";

matrix_multiply = load_inline(
    name="matrix_multiply",
    cpp_sources=matrix_multiply_cpp_source,
    cuda_sources=matrix_multiply_source,
    functions=["matrix_multiply_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matrix_multiply = matrix_multiply

    def forward(self, A, B):
        return self.matrix_multiply.matrix_multiply_cuda(A, B)

M = 16384
N = 16

def get_inputs():
    A = torch.randn(M, N, device="cuda")
    B = torch.randn(N, M, device="cuda")
    return [A, B]

def get_init_inputs():
    return []
